on conflict (kind, tmdb_id) where kind in ('movie', 'series') do update
  set wikidata_qid      = excluded.wikidata_qid,
      title             = excluded.title,
      release_date      = excluded.release_date,
      runtime_minutes   = excluded.runtime_minutes,
      original_language = excluded.original_language,
      genres            = excluded.genres,
      provenance        = excluded.provenance,
      fetched_at        = now();

-- Seasons. The parent is joined by its Wikidata id rather than named by a literal
-- uuid, because ids are generated at insert time and a refresh has to land on the
-- same row. A season whose parent is absent contributes nothing rather than failing:
-- the join drops it.
insert into media_items (kind, parent_id, season_number, title, release_date, provenance)
select 'season', parent.id, seed.season_number, seed.title, seed.release_date, 'wikidata'
  from (values
    ('Q105553568', 1, $seed$Season 1$seed$, '2022-11-23'::date),
    ('Q105553568', 2, $seed$Season 2$seed$, '2025-08-06'::date),
    ('Q105553568', 3, $seed$Season 3$seed$, null::date),
    ('Q106582931', 1, $seed$Season 1$seed$, '2021-09-17'::date),
    ('Q106582931', 2, $seed$Season 2$seed$, '2024-12-26'::date),
    ('Q106582931', 3, $seed$Season 3$seed$, '2025-06-27'::date),
    ('Q1077', 1, $seed$Season 1$seed$, '1966-09-07'::date),
    ('Q1077', 2, $seed$Season 2$seed$, '1967-09-14'::date),
    ('Q1077', 3, $seed$Season 3$seed$, '1968-09-19'::date),
    ('Q1079', 1, $seed$Season 1$seed$, '2008-01-20'::date),
    ('Q1079', 2, $seed$Season 2$seed$, '2009-03-08'::date),
    ('Q1079', 3, $seed$Season 3$seed$, '2010-03-21'::date),
